#[derive(Clone, Copy, Debug)] pub struct Sample {pub time_s:f64,pub coldest_c:f64,pub center_c:f64,pub mean_c:f64,pub pasteurization_s:f64}
#[derive(Clone, Debug)] pub struct Core {pub geometry:Geometry,pub boundary:Boundary,pub temperature:Vec<f64>,pub moisture:Vec<f64>,pub crust:Vec<bool>,pub time_s:f64,pub pasteurization_s:f64,pub ledger:Ledger,center:usize}
impl Core {
    pub fn new(geometry:Geometry,boundary:Boundary,initial_c:f64)->Self {let len=geometry.active.len();let mut temperature=vec![f64::NAN;len];let mut moisture=vec![0.0;len];
        for q in 0..len {if geometry.active[q]{temperature[q]=initial_c;}if geometry.area[q]>0.0{moisture[q]=boundary.initial_moisture_kg_m2;}}
        let c=(geometry.n as f64-1.0)/2.0;let mut center=0;let mut best=f64::INFINITY;for i in 0..geometry.n{for j in 0..geometry.n{for k in 0..geometry.n{let q=geometry.idx(i,j,k);if geometry.active[q]{let d=(i as f64-c).powi(2)+(j as f64-c).powi(2)+(k as f64-c).powi(2);if d<best{best=d;center=q;}}}}}
        Self{geometry,boundary,temperature,moisture,crust:vec![false;len],time_s:0.0,pasteurization_s:0.0,ledger:Ledger::default(),center}}
    }
    fn conduction(&self,p:&[Properties])->(Vec<f64>,Vec<f64>){let g=&self.geometry;let mut power=vec![0.0;g.active.len()];let mut sum=vec![0.0;g.active.len()];
        for axis in 0..3{for i in 0..g.n{for j in 0..g.n{for k in 0..g.n{let pos=[i,j,k];if pos[axis]+1>=g.n{continue}let mut hi=pos;hi[axis]+=1;let loq=g.idx(i,j,k);let hiq=g.idx(hi[0],hi[1],hi[2]);if !(g.active[loq]&&g.active[hiq]){continue}
            let frac=.5*(g.faces[2*axis+1][loq]+g.faces[2*axis][hiq]);let kk=2.0*p[loq].k*p[hiq].k/(p[loq].k+p[hiq].k).max(1e-12);let conductance=kk*frac*g.spacing;
            let flow=conductance*(self.temperature[hiq]-self.temperature[loq]);power[loq]+=flow;power[hiq]-=flow;sum[loq]+=conductance;sum[hiq]+=conductance;
        }}}} (power,sum)
    }
    fn saturation(temp:f64)->f64{let t=temp.clamp(0.0,99.0);let pressure=133.322*10f64.powf(8.07131-1730.63/(233.426+t));pressure/(461.5*(t+273.15))}
    fn surface(&self,rest:bool,dt:Option<f64>)->(Vec<f64>,[f64;4],Vec<f64>){let g=&self.geometry;let b=&self.boundary;let (air,wall,h,eps)=if rest{(b.ambient_c,b.ambient_c,b.rest_h*if b.foil_tent{.55}else{1.0},b.emissivity*if b.foil_tent{.35}else{1.0})}else{(b.oven_c,b.wall_c,b.h_conv,b.emissivity)};
        let mut net=vec![0.0;g.active.len()];let mut totals=[0.0;4];let mut hrad_out=vec![0.0;g.active.len()];for q in 0..g.active.len(){if g.area[q]<=1e-15{continue}let t=self.temperature[q];let conv=h*(air-t);let tk=t+273.15;let wk=wall+273.15;let hrad=eps*SIGMA*(wk+tk)*(wk*wk+tk*tk);let rad=hrad*(wall-t);hrad_out[q]=hrad;
            let mut evap=0.0;if self.moisture[q]>0.0&&!g.pan[q]{let hm=h/(1.18*1007.0*.9f64.powf(2.0/3.0));let mut potential=hm*(Self::saturation(t)-b.vapor_density_kg_m3).max(0.0);if b.covered{potential*=.02}if rest{potential*=.35}
                let available=(conv+rad).max(0.0)+25.0*(t-30.0).max(0.0);evap=(H_FG*potential).min(available);if let Some(d)=dt{evap=evap.min(self.moisture[q]*H_FG/d);}}
            let (conv,rad,evap)=if b.pan_insulated&&g.pan[q]{(0.0,0.0,0.0)}else{(conv,rad,evap)};net[q]=conv+rad-evap;totals[0]+=conv*g.area[q];totals[1]+=rad*g.area[q];totals[2]+=evap*g.area[q];totals[3]+=net[q]*g.area[q];
        }(net,totals,hrad_out)
    }
    pub fn stable_dt(&self,rest:bool)->f64{let p:Vec<_>=self.temperature.iter().enumerate().map(|(q,&t)|properties(if self.geometry.active[q]{t}else{5.0})).collect();let (_,mut conductance)=self.conduction(&p);let (_,_,hrad)=self.surface(rest,None);let h=if rest{self.boundary.rest_h}else{self.boundary.h_conv};let mut dt=f64::INFINITY;
        for q in 0..self.geometry.active.len(){if self.geometry.active[q]{conductance[q]+=self.geometry.area[q]*(h+hrad[q]+25.0);let cap=p[q].rho*p[q].cp*self.geometry.effective_fraction[q]*self.geometry.spacing.powi(3);dt=dt.min(cap/conductance[q].max(1e-20));}}(0.35*dt).min(5.0)}
    pub fn step(&mut self,dt:f64,rest:bool){let p:Vec<_>=self.temperature.iter().enumerate().map(|(q,&t)|properties(if self.geometry.active[q]{t}else{5.0})).collect();let (mut power,_)=self.conduction(&p);let (surface,totals,_)=self.surface(rest,Some(dt));let old=self.temperature.clone();let mut delta=0.0;
        for q in 0..power.len(){if self.geometry.active[q]{power[q]+=surface[q]*self.geometry.area[q];let cap=p[q].rho*p[q].cp*self.geometry.effective_fraction[q]*self.geometry.spacing.powi(3);self.temperature[q]=old[q]+dt*power[q]/cap;delta+=cap*(self.temperature[q]-old[q]);if totals[2]>0.0&&self.geometry.area[q]>0.0{let evap=(power[q]-(power[q]-surface[q]*self.geometry.area[q]));let _=evap;}}
            if self.geometry.area[q]>0.0 { // Recompute only the local evaporative term to advance the staged reservoir exactly.
                let t=old[q];let b=&self.boundary;let h=if rest{b.rest_h*if b.foil_tent{.55}else{1.0}}else{b.h_conv};let wall=if rest{b.ambient_c}else{b.wall_c};let eps=if rest{b.emissivity*if b.foil_tent{.35}else{1.0}}else{b.emissivity};let conv=h*((if rest{b.ambient_c}else{b.oven_c})-t);let tk=t+273.15;let wk=wall+273.15;let rad=eps*SIGMA*(wk+tk)*(wk*wk+tk*tk)*(wall-t);let mut evap=0.0;
                if self.moisture[q]>0.0&&!self.geometry.pan[q]{let hm=h/(1.18*1007.0*.9f64.powf(2.0/3.0));let mut potential=hm*(Self::saturation(t)-b.vapor_density_kg_m3).max(0.0);if b.covered{potential*=.02}if rest{potential*=.35}evap=(H_FG*potential).min((conv+rad).max(0.0)+25.0*(t-30.0).max(0.0)).min(self.moisture[q]*H_FG/dt);}
                if b.pan_insulated&&self.geometry.pan[q]{evap=0.0}self.moisture[q]=(self.moisture[q]-evap*dt/H_FG).max(0.0);if self.moisture[q]<=1e-12{self.crust[q]=true;}
            }}
        let expected=totals[3]*dt;self.ledger.convection_j+=totals[0]*dt;self.ledger.radiation_j+=totals[1]*dt;self.ledger.evaporation_j+=totals[2]*dt;self.ledger.net_surface_j+=expected;self.ledger.discrete_enthalpy_j+=delta;self.ledger.residual_j+=delta-expected;
        let cold=self.temperature.iter().copied().filter(|v|v.is_finite()).fold(f64::INFINITY,f64::min);self.pasteurization_s+=10f64.powf((cold-70.0)/7.5)*dt;self.time_s+=dt;
    }
    pub fn run_for(&mut self,duration:f64,rest:bool){let end=self.time_s+duration;while self.time_s<end-1e-10{let dt=self.stable_dt(rest).min(end-self.time_s);self.step(dt,rest)}}
    pub fn sample(&self)->Sample{let mut cold=f64::INFINITY;let mut sum=0.0;let mut count=0;for (q,&t) in self.temperature.iter().enumerate(){if self.geometry.active[q]{cold=cold.min(t);sum+=t;count+=1;}}Sample{time_s:self.time_s,coldest_c:cold,center_c:self.temperature[self.center],mean_c:sum/count as f64,pasteurization_s:self.pasteurization_s}}
    pub fn center_slice(&self)->Vec<f32>{let k=self.geometry.n/2;let mut out=Vec::with_capacity(self.geometry.n*self.geometry.n);for i in 0..self.geometry.n{for j in 0..self.geometry.n{out.push(self.temperature[self.geometry.idx(i,j,k)] as f32)}}out}
    pub fn moisture_remaining_kg(&self)->f64{self.moisture.iter().zip(&self.geometry.area).map(|(m,a)|m*a).sum()}
}

#[wasm_bindgen]
pub struct Simulation { core:Core }
#[wasm_bindgen]
impl Simulation {
    #[wasm_bindgen(constructor)]
    pub fn new(preset:&str,mass_kg:f64,resolution:usize,initial_c:f64,oven_c:f64,h_conv:f64,emissivity:f64,covered:bool)->Result<Simulation,JsValue>{
        let geometry=make_geometry(preset,mass_kg,resolution).map_err(|e|JsValue::from_str(&e))?;let mut boundary=Boundary::default();boundary.oven_c=oven_c;boundary.wall_c=oven_c;boundary.h_conv=h_conv;boundary.emissivity=emissivity;boundary.covered=covered;
        Ok(Self{core:Core::new(geometry,boundary,initial_c)})
    }
    pub fn run_chunk(&mut self,seconds:f64,rest:bool)->String{self.core.run_for(seconds.max(0.0),rest);self.summary_json()}
    pub fn summary_json(&self)->String{let s=self.core.sample();format!("{{\"time_s\":{:.12},\"coldest_c\":{:.9},\"center_c\":{:.9},\"mean_c\":{:.9},\"pasteurization_s\":{:.12},\"moisture_remaining_kg\":{:.12},\"energy_residual_j\":{:.9}}}",s.time_s,s.coldest_c,s.center_c,s.mean_c,s.pasteurization_s,self.core.moisture_remaining_kg(),self.core.ledger.residual_j)}
    pub fn center_slice(&self)->Vec<f32>{self.core.center_slice()}
    pub fn resolution(&self)->usize{self.core.geometry.n}
}

