@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&display=swap');

:root {
  --ink: #201d19;
  --muted: #716b62;
  --paper: #f5f1e9;
  --panel: #fffdf8;
  --line: #d9d1c5;
  --red: #c9472d;
  --red-dark: #9e321e;
  --gold: #e5a429;
  --blue: #397887;
  --shadow: 0 16px 45px rgba(52, 40, 26, .08);
  font-family: Manrope, system-ui, sans-serif;
  color: var(--ink);
  background: var(--paper);
  font-synthesis: none;
}
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; background: var(--paper); }
button, input, select { font: inherit; }
.site-header { height: 68px; padding: 0 max(24px, calc((100vw - 1440px)/2)); display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); background: rgba(245,241,233,.94); }
.brand { color: var(--ink); text-decoration: none; text-transform: uppercase; font-size: 17px; font-weight: 700; letter-spacing: .05em; }
.brand span { color: var(--red); }
.model-badge { font: 500 11px DM Mono, monospace; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.model-badge i { display: inline-block; width: 7px; height: 7px; margin-right: 7px; border-radius: 50%; background: #6c956b; box-shadow: 0 0 0 3px rgba(108,149,107,.15); }
main { width: min(1440px, 100%); margin: auto; padding: 0 24px 48px; }
.hero { min-height: 260px; padding: 52px 3.5% 44px; display: flex; align-items: end; justify-content: space-between; gap: 48px; }
.eyebrow { margin: 0 0 12px; color: var(--red); font: 500 11px DM Mono, monospace; letter-spacing: .13em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(40px, 5vw, 70px); line-height: .98; letter-spacing: -.055em; font-weight: 600; }
.lede { max-width: 670px; margin: 22px 0 0; color: var(--muted); font-size: 16px; line-height: 1.6; }
.honesty { max-width: 325px; padding: 16px 18px; margin: 0; border-left: 2px solid var(--gold); color: var(--muted); font-size: 12px; line-height: 1.55; background: rgba(255,255,255,.35); }
.honesty strong { color: var(--ink); text-transform: uppercase; letter-spacing: .08em; font: 500 10px DM Mono, monospace; }
.workspace { display: grid; grid-template-columns: minmax(300px, 390px) minmax(0, 1fr); gap: 18px; align-items: start; }
.panel, .metrics article { background: var(--panel); border: 1px solid var(--line); box-shadow: var(--shadow); }
.control-panel { position: sticky; top: 16px; padding: 26px; }
.panel-heading { min-height: 42px; margin-bottom: 22px; display: flex; align-items: start; justify-content: space-between; gap: 15px; }
.panel-heading > div:first-child { display: flex; align-items: baseline; gap: 11px; }
.step { color: var(--red); font: 500 10px DM Mono, monospace; letter-spacing: .08em; }
h2 { margin: 0; font-size: 17px; letter-spacing: -.02em; }
.engine-state { padding: 6px 8px; color: var(--muted); background: #eee9e0; font: 500 9px DM Mono, monospace; text-transform: uppercase; letter-spacing: .04em; white-space: nowrap; }
.engine-state.ready { color: #3c6c46; background: #e5eee3; }
.engine-state.error { color: #9e321e; background: #f6ded8; }
label { display: block; margin: 0 0 16px; color: #4e4840; font-size: 11px; font-weight: 700; letter-spacing: .025em; }
.unit { float: right; color: #989085; font: 400 10px DM Mono, monospace; }
input, select { width: 100%; height: 42px; margin-top: 7px; padding: 0 11px; border: 1px solid var(--line); border-radius: 0; outline: none; background: #faf7f1; color: var(--ink); font-size: 13px; transition: border .15s, box-shadow .15s; }
input:focus, select:focus { border-color: var(--red); box-shadow: 0 0 0 2px rgba(201,71,45,.1); }
.input-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 12px; }
.switch-row { min-height: 48px; margin: 2px 0 17px; padding: 9px 0; display: flex; justify-content: space-between; align-items: center; border-top: 1px solid #ebe5db; border-bottom: 1px solid #ebe5db; }
.switch-row strong { display: block; font-size: 11px; }
.switch-row small { color: var(--muted); font-size: 10px; }
.switch { position: relative; margin: 0; }
.switch input { position: absolute; opacity: 0; }
.switch span { display: block; width: 38px; height: 21px; border-radius: 15px; background: #cfc8bd; cursor: pointer; transition: background .2s; }
.switch span::after { content: ''; display: block; width: 15px; height: 15px; transform: translate(3px,3px); border-radius: 50%; background: white; box-shadow: 0 1px 4px #827a70; transition: transform .2s; }
.switch input:checked + span { background: var(--red); }
.switch input:checked + span::after { transform: translate(20px,3px); }
details { margin: 0 0 18px; border-bottom: 1px solid #ebe5db; }
summary { padding: 1px 0 14px; color: var(--muted); font: 500 10px DM Mono, monospace; text-transform: uppercase; cursor: pointer; }
.details-body { padding: 5px 0; }
.switch-row.compact { border-bottom: 0; margin-bottom: 5px; }
.actions { display: flex; gap: 8px; }
button { border: 0; cursor: pointer; }
.primary { flex: 1; height: 48px; padding: 0 17px; display: flex; align-items: center; justify-content: space-between; color: white; background: var(--red); font-size: 12px; font-weight: 700; transition: background .15s; }
.primary:hover { background: var(--red-dark); }
.primary:disabled { cursor: not-allowed; background: #aaa198; }
.primary b { font-size: 18px; font-weight: 400; }
.secondary { padding: 0 15px; color: var(--red-dark); border: 1px solid #d7b6ad; background: transparent; font-size: 11px; font-weight: 700; }
.progress-wrap { margin-top: 13px; }
.progress-track { height: 3px; overflow: hidden; background: #e7e0d6; }
.progress-track i { display: block; width: 2%; height: 100%; background: var(--red); transition: width .25s; }
.progress-wrap p { margin: 7px 0 0; color: var(--muted); font: 400 9px DM Mono, monospace; }
.results-column { display: grid; gap: 18px; min-width: 0; }
.metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.metrics article { min-height: 112px; padding: 17px; box-shadow: none; }
.metrics span, .slice-info span { display: block; color: var(--muted); font: 500 9px DM Mono, monospace; text-transform: uppercase; letter-spacing: .04em; }
.metrics strong { display: block; margin: 13px 0 4px; font-size: 24px; line-height: 1; letter-spacing: -.05em; }
.metrics small { color: #928a80; font-size: 9px; }
.pasteur-card { border-top: 2px solid var(--gold) !important; }
.chart-panel, .slice-panel { padding: 24px 26px 26px; }
.chart-legend { display: flex !important; gap: 14px !important; color: var(--muted); font: 400 9px DM Mono, monospace; }
.chart-legend span::before { content: ''; display: inline-block; width: 12px; height: 2px; margin: 0 5px 2px 0; background: currentColor; }
.chart-legend .cold { color: var(--red); }.chart-legend .center { color: var(--blue); }.chart-legend .mean { color: var(--gold); }
.canvas-shell { position: relative; min-height: 280px; }
.chart-shell canvas { width: 100%; height: 280px; display: block; }
.empty-state { position: absolute; inset: 0; display: grid; place-items: center; color: #9a9288; font: 400 10px DM Mono, monospace; text-align: center; }
.slice-heading { align-items: center; }
.segmented { display: flex !important; gap: 0 !important; border: 1px solid var(--line); }
.segmented button { padding: 7px 10px; color: var(--muted); background: transparent; font: 500 9px DM Mono, monospace; }
.segmented button.active { color: white; background: var(--ink); }
.slice-layout { display: grid; grid-template-columns: minmax(0, 1fr) 155px; gap: 22px; }
.slice-stage { position: relative; min-height: 350px; display: grid; place-items: center; overflow: hidden; background: #27241f; }
.slice-stage::after { content: 'CENTER PLANE'; position: absolute; left: 11px; top: 10px; color: rgba(255,255,255,.4); font: 400 8px DM Mono, monospace; letter-spacing: .1em; pointer-events: none; }
.slice-stage canvas { display: block; width: min(100%, 520px); height: 350px; image-rendering: pixelated; }
.slice-stage .empty-state { color: #999087; }
.slice-info { display: grid; align-content: start; gap: 0; }
.slice-info > div:not(.color-key) { padding: 12px 0; border-bottom: 1px solid #e5ded4; }
.slice-info strong { display: block; margin-top: 6px; font: 500 13px DM Mono, monospace; }
.color-key { margin-top: 18px; }
.key-item { margin-bottom: 8px; display: flex; align-items: center; gap: 7px; color: var(--muted); font-size: 9px; }
.key-item i { width: 18px; height: 7px; }
.method-note { margin-top: 18px; padding: 30px 3%; display: grid; grid-template-columns: 30px minmax(0,1fr) auto; gap: 16px; align-items: start; border: 1px solid var(--line); }
.method-note p { max-width: 850px; margin: 9px 0 0; color: var(--muted); font-size: 12px; line-height: 1.6; }
.method-note a { color: var(--red-dark); font: 500 10px DM Mono, monospace; text-decoration: none; }
footer { max-width: 1440px; margin: auto; padding: 23px 24px; display: flex; justify-content: space-between; border-top: 1px solid var(--line); color: var(--muted); font: 400 9px DM Mono, monospace; text-transform: uppercase; }
.sr-only { position: absolute; width: 1px; height: 1px; clip: rect(0,0,0,0); overflow: hidden; }
[hidden] { display: none !important; }

@media (max-width: 980px) {
  .hero { align-items: start; flex-direction: column; gap: 25px; }
  .workspace { grid-template-columns: 1fr; }
  .control-panel { position: static; }
  .metrics { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 620px) {
  main { padding: 0 12px 30px; }
  .site-header { padding: 0 15px; }
  .model-badge { font-size: 8px; }
  .hero { padding: 38px 4px 35px; min-height: auto; }
  .honesty { max-width: none; }
  .control-panel, .chart-panel, .slice-panel { padding: 20px 17px; }
  .slice-layout { grid-template-columns: 1fr; }
  .slice-info { grid-template-columns: 1fr 1fr; gap: 0 12px; }
  .color-key { grid-column: 1 / -1; }
  .chart-legend { display: none !important; }
  .method-note { grid-template-columns: 24px 1fr; }
  .method-note a { grid-column: 2; }
}

const $ = id => document.getElementById(id);
const form = $('simulation-form');
const runButton = $('run-button');
const cancelButton = $('cancel-button');
const progressWrap = $('progress-wrap');
const progressBar = $('progress-bar');
const progressText = $('progress-text');
const engineState = $('engine-state');
const curveCanvas = $('curve-canvas');
const sliceCanvas = $('slice-canvas');

let worker;
let running = false;
let curve = [];
let latestSlice = null;
let latestResolution = 0;
let latestSummary = null;
let colorMode = 'doneness';
let activeConfig = null;

const colors = {
  ink: '#39342e', grid: '#ded7cc', muted: '#887f74', cold: '#c9472d',
  center: '#397887', mean: '#d59820', rest: '#8375a1',
};

function number(id) { return Number($(id).value); }
function readConfig() {
  return {
    preset: $('preset').value,
    massKg: number('mass'),
    resolution: number('resolution'),
    initialC: number('initial'),
    ovenC: number('oven'),
    targetC: number('target'),
    hConv: number('convection'),
    emissivity: number('emissivity'),
    covered: $('covered').checked,
    maxRoastMinutes: number('max-hours') * 60,
    restMinutes: number('rest-minutes'),
    ambientC: number('ambient'),
    restH: number('rest-h'),
    foilTent: $('foil').checked,
    chunkSeconds: 30,
  };
}
function validate(config) {
  if (config.targetC <= config.initialC) return 'Pull target must exceed starting temperature.';
  if (config.ovenC <= config.targetC) return 'Oven temperature must exceed the pull target.';
  if (!Object.values(config).every(v => typeof v !== 'number' || Number.isFinite(v))) return 'All numeric inputs must be valid.';
  return '';
}
function setRunning(value) {
  running = value;
  runButton.disabled = value || !worker;
  cancelButton.hidden = !value;
  progressWrap.hidden = !value;
  form.querySelectorAll('input, select').forEach(input => { input.disabled = value; });
  runButton.querySelector('span').textContent = value ? 'Simulation running' : 'Run simulation';
}
function resetResults() {
  curve = [];
  latestSlice = null;
  latestSummary = null;
  ['pull-time', 'peak-core', 'carryover', 'pasteurization'].forEach(id => $(id).textContent = '—');
  $('pull-note').textContent = 'to coldest-point target';
  $('peak-note').textContent = 'after rest';
  updateLive(null);
  $('chart-empty').hidden = false;
  $('slice-empty').hidden = false;
  drawCurve();
  drawSlice();
}
function initializeWorker() {
  try {
    worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });
    worker.onmessage = onWorkerMessage;
    worker.onerror = event => fail(event.message || 'Worker failed to load.');
  } catch (error) { fail(error.message); }
}
function onWorkerMessage(event) {
  const message = event.data || {};
  if (message.type === 'ready') {
    engineState.textContent = 'Engine ready';
    engineState.className = 'engine-state ready';
    if (!running) runButton.disabled = false;
  } else if (message.type === 'progress') {
    if (!running) return;
    curve.push(message.summary);
    latestSummary = message.summary;
    latestSlice = message.slice;
    latestResolution = message.resolution;
    $('chart-empty').hidden = true;
    $('slice-empty').hidden = true;
    updateProgress(message.summary);
    updateLive(message.summary);
    drawCurve();
    drawSlice();
  } else if (message.type === 'complete') {
    curve = message.curve;
    latestSlice = message.slice;
    latestResolution = message.resolution;
    latestSummary = curve.at(-1);
    showResult(message.result);
    updateLive(latestSummary);
    drawCurve();
    drawSlice();
    setRunning(false);
  } else if (message.type === 'cancelled') {
    setRunning(false);
    progressText.textContent = 'Cancelled. Partial results remain visible.';
  } else if (message.type === 'error') {
    fail(message.message);
  }
}
function fail(message) {
  setRunning(false);
  engineState.textContent = 'Engine error';
  engineState.className = 'engine-state error';
  progressWrap.hidden = false;
  progressText.textContent = message || 'Simulation failed.';
  console.error(message);
}

form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.reportValidity() || running) return;
  const config = readConfig();
  const error = validate(config);
  if (error) { progressWrap.hidden = false; progressText.textContent = error; return; }
  activeConfig = config;
  resetResults();
  setRunning(true);
  progressBar.style.width = '2%';
  progressText.textContent = 'Voxelizing the signed-distance shape…';
  worker.postMessage({ type: 'start', config });
});
cancelButton.addEventListener('click', () => {
  if (running) worker.postMessage({ type: 'cancel' });
});
document.querySelectorAll('[data-color-mode]').forEach(button => {
  button.addEventListener('click', () => {
    colorMode = button.dataset.colorMode;
    document.querySelectorAll('[data-color-mode]').forEach(b => b.classList.toggle('active', b === button));
    drawSlice();
    updateColorKey();
  });
});

function updateProgress(summary) {
  const roastLimit = activeConfig.maxRoastMinutes * 60;
  let fraction;
  if (summary.mode === 'roast') {
    const byTime = summary.time_s / roastLimit;
    const byTemp = (summary.coldest_c - activeConfig.initialC) / (activeConfig.targetC - activeConfig.initialC);
    fraction = Math.max(byTime * .75, Math.min(.82, byTemp * .82));
    progressText.textContent = `Roasting · coldest ${formatTemp(summary.coldest_c)} · ${formatTime(summary.time_s)}`;
  } else {
    const roastEnd = curve.find(s => s.mode === 'rest')?.time_s || summary.time_s;
    const restFraction = activeConfig.restMinutes ? (summary.time_s - roastEnd) / (activeConfig.restMinutes * 60) : 1;
    fraction = .84 + .15 * restFraction;
    progressText.textContent = `Resting · coldest ${formatTemp(summary.coldest_c)} · ${formatTime(summary.time_s - roastEnd)}`;
  }
  progressBar.style.width = `${Math.max(2, Math.min(99, fraction * 100))}%`;
}
function showResult(result) {
  progressBar.style.width = '100%';
  const pull = result.pull;
  const restElapsed = Math.max(0, result.peak.time_s - pull.time_s);
  $('pull-time').textContent = formatTime(pull.time_s);
  $('pull-note').textContent = result.hitTarget ? `pulled at ${formatTemp(pull.coldest_c)}` : `target not reached (${formatTemp(pull.coldest_c)})`;
  $('peak-core').textContent = formatTemp(result.peak.coldest_c);
  $('peak-note').textContent = restElapsed ? `${formatTime(restElapsed)} after pull` : 'at pull';
  $('carryover').textContent = `${result.carryover_c >= 0 ? '+' : ''}${result.carryover_c.toFixed(1)}°C`;
  $('pasteurization').textContent = formatEquivalent(result.pasteurization_s);
  progressText.textContent = result.hitTarget ? 'Simulation complete.' : 'Maximum roast time reached before target; rest was still simulated.';
}
function updateLive(summary) {
  $('phase-value').textContent = summary ? (summary.mode === 'rest' ? 'Carryover rest' : 'Oven roast') : 'Ready';
  $('elapsed-value').textContent = summary ? formatTime(summary.time_s) : '—';
  $('cold-value').textContent = summary ? formatTemp(summary.coldest_c) : '—';
  $('moisture-value').textContent = summary ? `${(summary.moisture_remaining_kg * 1000).toFixed(1)} g` : '—';
}
const formatTemp = value => `${value.toFixed(1)}°C`;
function formatTime(seconds) {
  const totalMinutes = Math.max(0, Math.round(seconds / 60));
  const hours = Math.floor(totalMinutes / 60), minutes = totalMinutes % 60;
  return hours ? `${hours}h ${String(minutes).padStart(2, '0')}m` : `${minutes} min`;
}
function formatEquivalent(seconds) {
  if (seconds < .01) return '<0.01 s';
  if (seconds < 60) return `${seconds.toFixed(seconds < 10 ? 2 : 1)} s`;
  return `${(seconds / 60).toFixed(1)} min`;
}

function sizeCanvas(canvas) {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(devicePixelRatio || 1, 2);
  const width = Math.max(1, Math.round(rect.width * dpr));
  const height = Math.max(1, Math.round(rect.height * dpr));
  if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
  return { ctx: canvas.getContext('2d'), width, height, dpr };
}
function drawCurve() {
  const { ctx, width: w, height: h, dpr } = sizeCanvas(curveCanvas);
  ctx.clearRect(0, 0, w, h);
  if (curve.length < 2) return;
  const margin = { l: 43*dpr, r: 14*dpr, t: 8*dpr, b: 31*dpr };
  const plotW = w-margin.l-margin.r, plotH = h-margin.t-margin.b;
  const maxTime = Math.max(1, curve.at(-1).time_s);
  const values = curve.flatMap(s => [s.coldest_c, s.center_c, s.mean_c]);
  const minT = Math.floor((Math.min(...values)-5)/10)*10;
  const maxT = Math.ceil((Math.max(...values)+5)/10)*10;
  const rangeT = Math.max(10, maxT-minT);
  const x = t => margin.l + t/maxTime*plotW;
  const y = t => margin.t + (maxT-t)/rangeT*plotH;
  ctx.font = `${9*dpr}px DM Mono, ui-monospace, monospace`;
  ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
  for (let q=0; q<=4; q++) {
    const temp = minT + rangeT*q/4, yy = y(temp);
    ctx.strokeStyle = colors.grid; ctx.lineWidth = dpr*.6;
    ctx.beginPath(); ctx.moveTo(margin.l, yy); ctx.lineTo(w-margin.r, yy); ctx.stroke();
    ctx.fillStyle = colors.muted; ctx.fillText(`${Math.round(temp)}°`, margin.l-7*dpr, yy);
  }
  ctx.textBaseline = 'top';
  for (let q=0; q<=4; q++) {
    const time = maxTime*q/4, xx = x(time);
    ctx.textAlign = q===0 ? 'left' : q===4 ? 'right' : 'center';
    ctx.fillStyle = colors.muted; ctx.fillText(formatAxisTime(time), xx, h-margin.b+9*dpr);
  }
  const restStart = curve.find(s => s.mode === 'rest');
  if (restStart) {
    const xx = x(restStart.time_s);
    ctx.fillStyle = 'rgba(131,117,161,.08)'; ctx.fillRect(xx, margin.t, w-margin.r-xx, plotH);
    ctx.strokeStyle = colors.rest; ctx.setLineDash([3*dpr,3*dpr]);
    ctx.beginPath(); ctx.moveTo(xx, margin.t); ctx.lineTo(xx, margin.t+plotH); ctx.stroke(); ctx.setLineDash([]);
    ctx.textAlign='left'; ctx.textBaseline='top'; ctx.fillStyle=colors.rest; ctx.fillText('REST', xx+5*dpr, margin.t+4*dpr);
  }
  [['mean_c', colors.mean], ['center_c', colors.center], ['coldest_c', colors.cold]].forEach(([key,color]) => {
    ctx.beginPath(); curve.forEach((s,index) => { const xx=x(s.time_s), yy=y(s[key]); index ? ctx.lineTo(xx,yy) : ctx.moveTo(xx,yy); });
    ctx.strokeStyle=color; ctx.lineWidth=key==='coldest_c'?2*dpr:1.4*dpr; ctx.lineJoin='round'; ctx.stroke();
  });
}
function formatAxisTime(seconds) {
  const hours = seconds/3600;
  return hours >= 1 ? `${hours.toFixed(hours < 3 ? 1 : 0)}h` : `${Math.round(seconds/60)}m`;
}

const donenessStops = [
  { limit: -10, color: [74,43,76], label: '>10°C below target' },
  { limit: -3, color: [169,65,72], label: 'Approaching target' },
  { limit: 4, color: [221,136,92], label: 'At target band' },
  { limit: Infinity, color: [116,66,36], label: '>4°C over target' },
];
function drawSlice() {
  const { ctx, width: w, height: h } = sizeCanvas(sliceCanvas);
  ctx.fillStyle='#27241f'; ctx.fillRect(0,0,w,h);
  if (!latestSlice || !latestResolution) return;
  const n=latestResolution;
  const pixel=document.createElement('canvas'); pixel.width=n; pixel.height=n;
  const pctx=pixel.getContext('2d'); const image=pctx.createImageData(n,n);
  let min=activeConfig?.initialC ?? 0;
  let max=Math.max((activeConfig?.targetC ?? 60)+25, latestSummary?.mean_c ?? 80);
  for(let q=0;q<latestSlice.length;q++) {
    const t=latestSlice[q], o=q*4;
    if(!Number.isFinite(t)) { image.data[o+3]=0; continue; }
    const rgb=colorMode==='doneness' ? donenessColor(t-(activeConfig?.targetC ?? 60)) : thermalColor((t-min)/(max-min));
    image.data[o]=rgb[0]; image.data[o+1]=rgb[1]; image.data[o+2]=rgb[2]; image.data[o+3]=255;
  }
  pctx.putImageData(image,0,0);
  const scale=Math.min(w/n,h/n)*.88, dw=n*scale, dh=n*scale;
  ctx.imageSmoothingEnabled=false;
  ctx.drawImage(pixel,(w-dw)/2,(h-dh)/2,dw,dh);
}
function donenessColor(delta) { return donenessStops.find(stop => delta < stop.limit).color; }
function thermalColor(value) {
  const stops=[[28,35,70],[43,95,133],[58,157,143],[230,183,72],[202,64,42],[247,230,180]];
  const x=Math.max(0,Math.min(.999,value))*(stops.length-1), i=Math.floor(x), f=x-i;
  return stops[i].map((v,q)=>Math.round(v+(stops[Math.min(i+1,stops.length-1)][q]-v)*f));
}
function updateColorKey() {
  const key=$('color-key');
  if(colorMode==='doneness') {
    key.innerHTML=donenessStops.map(stop=>`<div class="key-item"><i style="background:rgb(${stop.color})"></i>${stop.label}</div>`).join('');
  } else {
    key.innerHTML='<div class="key-item"><i style="background:linear-gradient(90deg,#1c2346,#3a9d8f,#e6b748,#ca402a)"></i>Cool → hot</div>';
  }
}

new ResizeObserver(() => { drawCurve(); drawSlice(); }).observe(document.querySelector('.results-column'));
updateColorKey();
resetResults();
initializeWorker();

