{
  "name": "roast-solver",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build": "node web/scripts/build.mjs",
    "check:web": "node web/scripts/check.mjs",
    "preview": "node web/scripts/serve.mjs",
    "test": "npm run test:python && npm run test:rust && npm run test:web",
    "test:python": "cd python && PYTHONPATH=. python -m pytest -q",
    "test:rust": "cargo test --locked --manifest-path web-core/Cargo.toml",
    "test:web": "node --check web/app.js && node --check web/worker.js && node --check web/scripts/build.mjs && node --check web/scripts/check.mjs && node --check web/scripts/serve.mjs"
  },
  "engines": {
    "node": ">=20"
  }
}

{
  description = "Roast Solver M1-M6 reference, WASM app, and validation environment";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    rust-overlay.url = "github:oxalica/rust-overlay";
    rust-overlay.inputs.nixpkgs.follows = "nixpkgs";
  };

  outputs = { self, nixpkgs, rust-overlay }:
    let
      systems = [ "x86_64-linux" "aarch64-linux" "x86_64-darwin" "aarch64-darwin" ];
      forAllSystems = nixpkgs.lib.genAttrs systems;
    in {
      packages = forAllSystems (system:
        let
          pkgs = import nixpkgs { inherit system; overlays = [ (import rust-overlay) ]; };
          rust = pkgs.rust-bin.stable.latest.default.override {
            extensions = [ "rustfmt" ];
            targets = [ "wasm32-unknown-unknown" ];
          };
          wasmBindgen = pkgs.wasm-bindgen-cli_0_2_126 or pkgs.wasm-bindgen-cli;
          cargoDeps = pkgs.rustPlatform.importCargoLock {
            lockFile = ./web-core/Cargo.lock;
          };
        in {
          default = pkgs.stdenvNoCC.mkDerivation {
            pname = "roast-solver-static";
            version = "0.1.0";
            src = self;
            inherit cargoDeps;
            cargoRoot = "web-core";
            nativeBuildInputs = [
              rust
              pkgs.rustPlatform.cargoSetupHook
              wasmBindgen
              pkgs.nodejs_22
            ];
            buildPhase = ''
              runHook preBuild
              cargo build --locked --manifest-path web-core/Cargo.toml \
                --target wasm32-unknown-unknown --release
              mkdir -p dist/wasm dist/docs
              wasm-bindgen \
                web-core/target/wasm32-unknown-unknown/release/roast_solver_web_core.wasm \
                --target web --out-dir dist/wasm
              cp web/index.html web/styles.css web/app.js web/worker.js dist/
              cp docs/PHYSICS.md docs/VALIDATION.md docs/CALIBRATION.md docs/PARITY.md dist/docs/
              node web/scripts/check.mjs
              runHook postBuild
            '';
            installPhase = ''
              runHook preInstall
              mkdir -p $out
              cp -R dist/. $out/
              runHook postInstall
            '';
          };
        });

      checks = forAllSystems (system:
        let
          pkgs = import nixpkgs { inherit system; overlays = [ (import rust-overlay) ]; };
          rust = pkgs.rust-bin.stable.latest.default.override { extensions = [ "rustfmt" ]; };
          python = pkgs.python312.withPackages (p: [ p.numpy p.pytest ]);
          cargoDeps = pkgs.rustPlatform.importCargoLock {
            lockFile = ./web-core/Cargo.lock;
          };
        in {
          python = pkgs.runCommand "roast-solver-python-tests" {
            nativeBuildInputs = [ python ];
          } ''
            cp -R ${self} source
            chmod -R u+w source
            cd source/python
            PYTHONPATH=. pytest -q
            touch $out
          '';

          rust = pkgs.stdenv.mkDerivation {
            pname = "roast-solver-rust-tests";
            version = "0.1.0";
            src = self;
            inherit cargoDeps;
            cargoRoot = "web-core";
            nativeBuildInputs = [ rust pkgs.rustPlatform.cargoSetupHook ];
            buildPhase = ''
              runHook preBuild
              cargo test --locked --manifest-path web-core/Cargo.toml
              cargo fmt --manifest-path web-core/Cargo.toml --all -- --check
              runHook postBuild
            '';
            installPhase = ''
              touch $out
            '';
          };

          web = self.packages.${system}.default;
        });

      devShells = forAllSystems (system:
        let
          pkgs = import nixpkgs { inherit system; overlays = [ (import rust-overlay) ]; };
          rust = pkgs.rust-bin.stable.latest.default.override {
            extensions = [ "rustfmt" ];
            targets = [ "wasm32-unknown-unknown" ];
          };
          python = pkgs.python312.withPackages (p: [ p.numpy p.pytest ]);
        in {
          default = pkgs.mkShell {
            packages = [
              python
              rust
              pkgs.wasm-pack
              (pkgs.wasm-bindgen-cli_0_2_126 or pkgs.wasm-bindgen-cli)
              pkgs.nodejs_22
              pkgs.pkg-config
            ];
            shellHook = ''
              export PYTHONPATH="$PWD/python''${PYTHONPATH:+:$PYTHONPATH}"
              echo "Roast Solver shell: npm test | npm run build | npm run preview"
            '';
          };
        });
    };
}

import { cp, mkdir, rm } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = dirname(fileURLToPath(import.meta.url));
const root = resolve(scriptDir, '../..');
const web = join(root, 'web');
const dist = join(root, 'dist');

await rm(dist, { recursive: true, force: true });
await mkdir(join(dist, 'wasm'), { recursive: true });

console.log('Building Rust core for wasm32…');
const result = spawnSync('wasm-pack', [
  'build', join(root, 'web-core'), '--target', 'web',
  '--out-dir', '../dist/wasm', '--release',
], { cwd: root, stdio: 'inherit' });
if (result.error?.code === 'ENOENT') {
  console.error('\nwasm-pack was not found. Enter `nix develop` or install wasm-pack, then retry.');
  process.exit(1);
}
if (result.status !== 0) process.exit(result.status ?? 1);

await Promise.all(['index.html', 'styles.css', 'app.js', 'worker.js'].map(file =>
  cp(join(web, file), join(dist, file))
));
await mkdir(join(dist, 'docs'), { recursive: true });
await Promise.all(['PHYSICS.md', 'VALIDATION.md', 'CALIBRATION.md', 'PARITY.md'].map(file =>
  cp(join(root, 'docs', file), join(dist, 'docs', file))
));
console.log(`Production site built at ${dist}`);

import { readFile, stat } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const root = resolve('dist');
const required = ['index.html','styles.css','app.js','worker.js','wasm/roast_solver_web_core.js','wasm/roast_solver_web_core_bg.wasm'];
for (const path of required) {
  const info = await stat(join(root, path));
  if (!info.isFile() || info.size === 0) throw new Error(`Missing or empty build asset: ${path}`);
}
const [html, app, worker] = await Promise.all(['index.html','app.js','worker.js'].map(p => readFile(join(root,p),'utf8')));
for (const id of ['simulation-form','curve-canvas','slice-canvas','pasteurization','carryover']) {
  if (!html.includes(`id="${id}"`)) throw new Error(`UI contract missing #${id}`);
}
if (!app.includes("new Worker(new URL('./worker.js'")) throw new Error('App does not construct the module worker');
if (!worker.includes("from './wasm/roast_solver_web_core.js'")) throw new Error('Worker does not import production WASM');
console.log(`Static build check passed (${required.length} required assets and UI/worker contracts).`);

import { createReadStream, existsSync, statSync } from 'node:fs';
import { createServer } from 'node:http';
import { extname, resolve, sep } from 'node:path';

const root = resolve('dist');
const port = Number(process.env.PORT || process.argv[2] || 4173);
const types = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.wasm': 'application/wasm',
  '.json': 'application/json; charset=utf-8', '.md': 'text/markdown; charset=utf-8',
};
if (!existsSync(root)) {
  console.error('dist/ does not exist. Run `npm run build` first.');
  process.exit(1);
}
const server = createServer((request, response) => {
  const pathname = decodeURIComponent(new URL(request.url, 'http://localhost').pathname);
  let file = resolve(root, `.${pathname === '/' ? '/index.html' : pathname}`);
  if (file !== root && !file.startsWith(root + sep)) {
    response.writeHead(403).end('Forbidden'); return;
  }
  if (existsSync(file) && statSync(file).isDirectory()) file = resolve(file, 'index.html');
  if (!existsSync(file)) { response.writeHead(404).end('Not found'); return; }
  response.writeHead(200, {
    'Content-Type': types[extname(file)] || 'application/octet-stream',
    'Content-Length': statSync(file).size,
    'Cache-Control': 'no-cache',
    'Cross-Origin-Opener-Policy': 'same-origin',
    'Cross-Origin-Embedder-Policy': 'require-corp',
  });
  if (request.method === 'HEAD') response.end();
  else createReadStream(file).pipe(response);
});
server.listen(port, '127.0.0.1', () => console.log(`Roast Solver: http://127.0.0.1:${port}`));

