  const slice = sim.center_slice();
  self.postMessage({
    type: 'complete', resolution: sim.resolution(), slice, curve,
    result: {
      pull, peak, hitTarget,
      carryover_c: peak.coldest_c - pull.coldest_c,
      pasteurization_s: summary.pasteurization_s,
